// Data for the street fly-in on the box office (frames generated by flow-videos/encode.sh).

export const STREET_FRAMES = 359; // street/{d,m}/001.webp ... 359.webp, 12 per second of footage

// The blank marquee board, hand-keyframed in desktop frame space (1280x720): [x1, y1, x2, y2].
// The name is lit on the board between these frames; positions in between are interpolated.
const BOARD: Record<number, [number, number, number, number]> = {
  120: [435, 262, 851, 365],
  136: [454, 285, 826, 384],
  150: [448, 291, 832, 400],
  164: [400, 320, 877, 435],
  178: [352, 346, 947, 492],
  192: [282, 330, 1005, 512],
  198: [280, 262, 1013, 478],
};
const KEYS = Object.keys(BOARD).map(Number).sort((a, b) => a - b);
export const BOARD_FROM = 116;
export const BOARD_TO = 200;

export function boardAt(frame: number): [number, number, number, number] {
  if (frame <= KEYS[0]) return BOARD[KEYS[0]];
  for (let i = 0; i < KEYS.length - 1; i++) {
    const a = KEYS[i];
    const b = KEYS[i + 1];
    if (frame >= a && frame <= b) {
      const t = (frame - a) / (b - a);
      return BOARD[a].map((v, j) => v + (BOARD[b][j] - v) * t) as [number, number, number, number];
    }
  }
  return BOARD[KEYS[KEYS.length - 1]];
}

/** The phone frames are a centre 9:16 slice of the desktop frame. */
export const PHONE_SLICE = { x: (656 / 1920) * 1280, w: (608 / 1920) * 1280 }; // in desktop frame px
